<template><div class="tree"><div v-for="(children,id) in modelValue" :key="id" class="node"><div><strong>{{ nodeName(id) }}</strong><button type="button" @click="remove(id)">移除节点及子级</button></div><MapTopologyEditor :model-value="children" :nodes="nodes" :used="new Set([...used,id])" @update:model-value="update(id,$event)" /></div><div class="add"><select v-model="candidate"><option value="">选择要添加的地图节点</option><option v-for="(node,id) in available" :key="id" :value="id">{{node.key||node.desc||'未命名节点'}}</option></select><button type="button" :disabled="!candidate" @click="add">+ 添加节点</button></div></div></template>
<script setup lang="ts">import{computed,ref}from'vue';import type{MapTopology}from'../scenario/types';defineOptions({name:'MapTopologyEditor'});const props=withDefaults(defineProps<{modelValue:MapTopology;nodes:Record<string,any>;used?:Set<string>}>(),{used:()=>new Set<string>()});const emit=defineEmits<{'update:modelValue':[value:MapTopology]}>();const candidate=ref('');const available=computed(()=>Object.fromEntries(Object.entries(props.nodes).filter(([id])=>!props.used.has(id)&&!(id in props.modelValue))));function nodeName(id:string){return props.nodes[id]?.key||props.nodes[id]?.desc||'已缺失的节点'}function add(){if(!candidate.value)return;emit('update:modelValue',{...props.modelValue,[candidate.value]:{}});candidate.value=''}function remove(id:string){const next={...props.modelValue};delete next[id];emit('update:modelValue',next)}function update(id:string,children:MapTopology){emit('update:modelValue',{...props.modelValue,[id]:children})}</script>
<style scoped>.tree{display:grid;gap:8px}.node{padding:9px 9px 9px 14px;border-left:2px solid #cbb477;background:#15181a}.node>div:first-child,.add{display:flex;justify-content:space-between;gap:8px}.add select{flex:1}</style>
